#!/usr/bin/env python3

from __future__ import annotations

import argparse
import json
from collections import defaultdict
from dataclasses import dataclass, asdict
from datetime import datetime
from pathlib import Path
from typing import Any

SEVERITY_RANK = {"low": 1, "medium": 2, "high": 3, "critical": 4}

@dataclass(frozen=True)
class Finding:
    rule: str
    severity: str
    reason: str
    event_ids: list[str]


def parse_time(value: str) -> datetime:
    return datetime.fromisoformat(value.replace("Z", "+00:00"))


def validate_events(events: Any) -> list[dict[str, Any]]:
    if not isinstance(events, list):
        raise ValueError("Input must be a JSON array")
    required = {"id", "timestamp", "event_type", "username", "source_ip", "host"}
    for item in events:
        if not isinstance(item, dict):
            raise ValueError("Every event must be an object")
        missing = required - item.keys()
        if missing:
            raise ValueError(f"Missing fields: {sorted(missing)}")
        parse_time(str(item["timestamp"]))
    return events


def detect(events: list[dict[str, Any]]) -> list[Finding]:
    ordered = sorted(events, key=lambda e: parse_time(str(e["timestamp"])))
    failures: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    findings: list[Finding] = []

    for event in ordered:
        key = (str(event["username"]), str(event["source_ip"]))
        if event["event_type"] == "login_failure":
            failures[key].append(event)
        elif event["event_type"] == "login_success":
            prior = failures.get(key, [])
            recent = [f for f in prior if (parse_time(str(event["timestamp"])) - parse_time(str(f["timestamp"]))).total_seconds() <= 900]
            if len(recent) >= 5:
                findings.append(Finding(
                    rule="AUTH-SEQ-01",
                    severity="high",
                    reason="A successful login followed at least five failures for the same user and source within 15 minutes.",
                    event_ids=[r["id"] for r in recent] + [event["id"]],
                ))

        if event["event_type"] == "privileged_change" and event.get("approved_change") is not True:
            findings.append(Finding(
                rule="PRIV-CHANGE-01",
                severity="high",
                reason="A privileged change lacks an approved-change marker in the supplied event data.",
                event_ids=[str(event["id"])],
            ))

    return findings


def build_report(events: list[dict[str, Any]]) -> dict[str, Any]:
    findings = detect(events)
    highest = max((f.severity for f in findings), key=lambda s: SEVERITY_RANK[s], default="low")
    return {
        "event_count": len(events),
        "finding_count": len(findings),
        "highest_severity": highest,
        "findings": [asdict(f) for f in findings],
        "analyst_guidance": [
            "Validate whether the observed activity is expected.",
            "Correlate identity, endpoint, and network evidence before escalation.",
            "Preserve relevant evidence before destructive containment where practical.",
            "Escalate according to the approved incident-response procedure when compromise is credible."
        ]
    }


def main() -> int:
    parser = argparse.ArgumentParser(description="Defensive SOC triage training tool")
    parser.add_argument("events", type=Path)
    parser.add_argument("--output", type=Path)
    args = parser.parse_args()

    events = validate_events(json.loads(args.events.read_text(encoding="utf-8")))
    rendered = json.dumps(build_report(events), indent=2)
    if args.output:
        args.output.write_text(rendered + "\n", encoding="utf-8")
    else:
        print(rendered)
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
